// Find the earliest Friday the 13th and count them in a 400-year cycle
// using the proleptic Gregorian calendar.

// --- Earliest Friday the 13th from 0001-01-01 ---
var date = new DateTime(1, 1, 13); // start on the first 13th
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date.DayOfWeek})");

// --- Count Friday the 13ths in a full 400-year Gregorian cycle ---
int count = 0;
var start = new DateTime(1, 1, 13);
var end = new DateTime(401, 1, 1);

for (var d = start; d < end; d = d.AddMonths(1))
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        count++;
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// --- Bonus: breakdown by day-of-week for all 13ths ---
var dowCounts = new int[7];
for (var d = start; d < end; d = d.AddMonths(1))
    dowCounts[(int)d.DayOfWeek]++;

Console.WriteLine("\n13th-of-month distribution over 400 years:");
foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-10} {dowCounts[(int)dow]}");

